(() => {
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((v||0)/100);
  const date=v=>v?String(v).slice(0,10).split('-').reverse().join('/'):'—';
  const types={income:'Recebimento',expense:'Pagamento',commission:'Comissão',consultancy:'Consultoria',transfer:'Transferência',opening:'Saldo inicial'};
  const statuses={open:'Em aberto',overdue:'Vencido',partial:'Parcial',paid:'Baixado',canceled:'Cancelado'};
  const paid=e=>e.legacyPaid?e.amountCents:e.payments.reduce((s,p)=>s+p.amountCents,0);
  const status=(e,today)=>e.canceled?'canceled':paid(e)>=e.amountCents?'paid':paid(e)?'partial':e.dueDate<today?'overdue':'open';
  let filters={},tab='entries',generation=0;
  window.TravelFinance={mount(root,{api,trips=[]}){
    let data,insights,selected,busy=false,loadId=0,granatum={connected:false};
    const initialQuery=new URLSearchParams(location.search);if(initialQuery.has('client')){filters.clientId=initialQuery.get('client');filters.allTime='1';tab='clients';}
    const token=++generation,alive=()=>root.isConnected&&generation===token;
    const request=(path,method='GET',body)=>api.request('/finance'+path,{method,...(body===undefined?{}:{body})});
    const query=()=>new URLSearchParams(filters).toString();
    const options=(values,current,empty='Todos')=>`<option value="">${empty}</option>`+Object.entries(values).map(([v,n])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(n)}</option>`).join('');
    const cats=(kind,current,manual=false)=>Object.fromEntries(data.catalogs.filter(c=>c.kind===kind&&(!c.archived||c.id===current)&&!(manual&&c.source==='granatum')).map(c=>[c.id,c.name+(c.archived?' (arquivado)':'')]));
    const input=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
    const select=(name,label,values,value='',empty='Selecione')=>`<label>${label}<select name="${name}">${options(values,value,empty)}</select></label>`;
    const button=(action,label,id='',extra='')=>`<button type="button" data-fin-action="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
    const name=id=>data.catalogs.find(c=>c.id===id)?.name||'Não definido';
    const notice=message=>{const el=root.querySelector('[data-fin-notice]');if(el){el.textContent=message;el.hidden=false;}};
    async function load(){const current=++loadId;try{const [next,connection]=await Promise.all([request('?'+query()),request('/granatum').catch(e=>({connected:false,error:e.message}))]);granatum=connection;if(!alive()||current!==loadId)return;data=next;filters={...next.filters,...(filters.allTime?{allTime:filters.allTime}:{})};if(['operations','clients'].includes(tab))insights=await request('/insights?'+query());if(!alive()||current!==loadId)return;delete filters.today;delete filters.pageSize;draw();return true;}catch(e){if(alive())notice(e.message);return false;}}
    function draw(){root.innerHTML=`<header class="fin-heading"><div><span class="fin-eyebrow">GESTÃO DA AGÊNCIA</span><h1>Financeiro</h1><p>Caixa, resultado das viagens e relacionamento com seus clientes.</p></div><div>${button('reports','Baixar relatório')}${button('new','+ Lançamento','','class="fin-primary"')}</div></header><p data-fin-notice role="alert" hidden></p><nav class="fin-tabs" aria-label="Visões financeiras">${[['entries','Lançamentos'],['operations','Resultado por viagem'],['clients','Clientes e histórico'],['flow','Fluxo de caixa'],['catalogs','Contas e cadastros']].map(([id,label])=>button('tab',label,id,`aria-current="${tab===id?'page':'false'}"`)).join('')}</nav>${tab==='entries'?granatumView():''}${tab==='catalogs'?catalogView():['operations','clients'].includes(tab)?insightFilters()+(tab==='operations'?operationsView():clientsView()):filterView()+(tab==='flow'?flowView():entriesView())}<dialog id="finance-dialog"><header><h2 data-fin-title></h2>${button('close','Fechar')}</header><div data-fin-body></div><p data-fin-error role="alert" hidden></p></dialog>`;}
    function granatumView(){if(!granatum.connected)return granatum.error?`<p class="fin-warning">${esc(granatum.error)}</p>`:'';return `<section class="fin-panel fin-connection"><div><strong>Granatum conectado</strong><p class="fin-muted">${granatum.lastSync?'Última leitura: '+esc(new Date(granatum.lastSync).toLocaleString('pt-BR')):'Primeira importação em andamento.'}${granatum.stats?.entries!=null?' · '+granatum.stats.entries+' lançamentos':''}. Atualizações automáticas a cada hora. ${granatum.running?'Uma leitura está em andamento.':''}</p>${granatum.error?`<p role="alert" class="fin-warning">${esc(granatum.error)}</p>`:''}</div><div class="fin-actions">${granatum.stats?.from?button('granatum-range','Ver todo o período'):''}${data.manager?button('granatum-sync',granatum.running?'Continuar sincronização':'Sincronizar agora'):''}${data.manager&&granatum.error?button('granatum-restart','Reiniciar leitura'):''}</div></section>`;}
    function granatumDetails(e){const g=e.granatum||{};return `<section class="fin-warning"><strong>Origem: Granatum</strong>${e.type==='opening'?'<p>Saldo inicial da conta. Este valor não compõe receitas nem despesas.</p>':''}<p>Altere este lançamento no Granatum. A próxima sincronização atualizará o TravelPro.</p>${g.center?`<p>Centro de custo / lucro: ${esc(g.center)}</p>`:''}${g.paymentMethod?`<p>Forma de pagamento: ${esc(g.paymentMethod)}</p>`:''}${g.tags?.length?`<p>Tags: ${g.tags.map(esc).join(', ')}</p>`:''}${g.infinite?'<p>Recorrência contínua: as próximas ocorrências entrarão conforme forem disponibilizadas pelo Granatum.</p>':''}${g.attachments?.length?`<p>${g.attachments.length} anexo(s) disponível(is) no Granatum. Os arquivos permanecem na origem.</p>`:''}<small>Referência: ${esc(e.externalId)}</small></section>`;}
    function filterView(){
      const advancedActive=(filters.basis&&filters.basis!=='dueDate')||['type','status','accountId','categoryId','personId','source','clientId','tripId'].some(key=>filters[key]);
      return `<form data-fin-form="filter" class="fin-filters"><div class="fin-filter-basic">${input('from','De',filters.from,'date','required')}${input('to','Até',filters.to,'date','required')}${input('q','Buscar descrição ou documento',filters.q)}<div class="fin-filter-actions"><button class="fin-primary">Aplicar filtros</button>${button('refresh','Atualizar')}</div></div><details class="fin-filter-advanced"${advancedActive?' open':''}><summary>Mais filtros${advancedActive?' · filtros ativos':''}</summary><div class="fin-filter-fields">${select('basis','Período por',{dueDate:'Vencimento',competenceDate:'Competência'},filters.basis)}${select('type','Tipo',types,filters.type,'Todos')}${select('status','Situação',statuses,filters.status,'Ativos')}${select('accountId','Conta',cats('account'),filters.accountId,'Todas')}${select('categoryId','Categoria',cats('category'),filters.categoryId,'Todas')}${select('personId','Cliente / fornecedor',cats('person'),filters.personId,'Todos')}${select('clientId','Cliente da agência',clientOptions(),filters.clientId,'Todos')}${select('tripId','Viagem',tripOptions(),filters.tripId,'Todas')}${select('source','Origem',{manual:'TravelPro',legacy:'Histórico anterior',granatum:'Granatum'},filters.source,'Todas')}</div></details></form>`;
    }
    function entriesView(){const s=data.summary;return `<div class="fin-summary">${[['A receber',s.receivable],['A pagar',s.payable],['Recebido',s.received],['Pago',s.paid]].map(([label,value])=>`<article><span>${label}</span><strong>${money(value)}</strong></article>`).join('')}</div><p class="fin-muted">Totais dos lançamentos filtrados. Em atraso: ${money(s.overdue)}.${s.legacyUndated?` ${s.legacyUndated} baixa(s) antiga(s) sem data; consulte o lançamento para regularizar.`:''}</p><div class="fin-table"><table><thead><tr><th>Descrição</th><th>Vencimento / competência</th><th>Conta / categoria</th><th>Situação</th><th>Valor / em aberto</th><th></th></tr></thead><tbody>${data.items.map(e=>`<tr><td><strong>${esc(e.title)}</strong><small>${types[e.serviceType==='consultancy'?'consultancy':e.serviceType==='commission'?'commission':e.type]}${e.installment?` · ${e.installment.number}/${e.installment.total}`:''} · ${e.source==='legacy'?'Histórico':e.source==='granatum'?'Granatum':'TravelPro'}</small>${e.personId?`<small>${esc(name(e.personId))}</small>`:''}</td><td>${date(e.dueDate)}<small>${date(e.competenceDate)}</small></td><td>${esc(name(e.accountId))}<small>${esc(e.type==='transfer'?name(e.toAccountId):name(e.categoryId))}</small></td><td><span class="fin-status fin-${status(e,data.today)}">${statuses[status(e,data.today)]}</span>${e.legacyPaid?'<small>Sem data da baixa</small>':''}</td><td><strong>${money(e.type==='opening'?e.openingSignedCents:e.amountCents)}</strong><small>${money(e.canceled?0:e.amountCents-paid(e))}</small></td><td>${button('detail','Abrir',e.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="fin-empty">Nenhum lançamento neste período. Ajuste os filtros ou crie um lançamento.</td></tr>'}</tbody></table></div><footer class="fin-pagination"><span>${data.total} lançamentos · página ${filters.page} de ${Math.max(1,Math.ceil(data.total/50))}</span><div>${button('previous','Anterior','',filters.page<=1?'disabled':'')}${button('next','Próxima','',filters.page*50>=data.total?'disabled':'')}</div></footer>`;}
    function flowView(){return `<section class="fin-panel"><h2>Realizado e previsto por mês</h2><p class="fin-muted">Realizado pela data de cada baixa; previsão pelo vencimento do saldo em aberto. Transferências e baixas antigas sem data não entram no realizado. Os demais filtros também se aplicam.</p><div class="fin-table"><table><thead><tr><th>Mês</th><th>Recebido</th><th>Pago</th><th>A receber</th><th>A pagar</th><th>Resultado realizado</th><th>Resultado previsto*</th></tr></thead><tbody>${data.monthly.map(m=>`<tr><td>${esc(m.month)}</td>${[m.received,m.paid,m.receivable,m.payable,m.received-m.paid,m.received-m.paid+m.receivable-m.payable].map(v=>`<td>${money(v)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">Sem movimentos no período.</td></tr>'}</tbody></table></div><p class="fin-muted">*Realizado mais valores em aberto. Não representa o saldo acumulado das contas.</p></section>`;}
    function catalogView(){return `<p class="fin-muted">Contas TravelPro: saldo inicial mais baixas. Contas Granatum: saldo informado na última leitura. Os saldos não dependem dos filtros.</p>${[['account','Contas'],['category','Categorias'],['person','Clientes e fornecedores']].map(([kind,title])=>`<section class="fin-panel"><div class="fin-heading"><h2>${title}</h2>${data.manager?button('catalog-new','+ Adicionar',kind):''}</div><div class="fin-catalogs">${data.catalogs.filter(c=>c.kind===kind).map(c=>`<article><div><strong>${esc(c.name)}</strong><small>${c.source==='granatum'&&kind==='account'?`Saldo informado pelo Granatum em ${date(c.balanceAt)}`:c.archived?'Arquivado':kind==='category'?({income:'Receitas',expense:'Despesas',both:'Receitas e despesas'}[c.type]):kind==='person'?({client:'Cliente',supplier:'Fornecedor',both:'Cliente e fornecedor'}[c.role]):`Saldo inicial: ${money(c.openingCents)} em ${date(c.openingDate)}`}</small>${kind==='account'?`<h3>${money(data.balances.find(b=>b.id===c.id)?.balanceCents)}</h3>`:''}</div>${data.manager&&c.source!=='granatum'?`<div>${button('catalog-edit','Editar',c.id)}${button('archive',c.archived?'Reativar':'Arquivar',c.id)}</div>`:''}</article>`).join('')||'<p class="fin-muted">Nenhum cadastro ainda.</p>'}</div></section>`).join('')}`;}
    function modal(title,html){const d=root.querySelector('dialog');d.querySelector('[data-fin-title]').textContent=title;d.querySelector('[data-fin-body]').innerHTML=html;d.querySelector('[data-fin-error]').hidden=true;if(!d.open)d.showModal();}
    const form=(kind,html)=>`<form data-fin-form="${kind}" class="fin-form">${html}<div class="fin-form-footer"><button class="fin-primary">Salvar</button>${button('close','Cancelar')}</div></form>`;
    function entryForm(e){selected=e||null;modal(e?'Editar lançamento':'Novo lançamento',form('entry',`<input type="hidden" name="requestId" value="${crypto.randomUUID()}">${input('title','Descrição',e?.title,'text','required maxlength="200"')}${select('type','Tipo',Object.fromEntries(Object.entries(types).filter(([k])=>k!=='opening')),e?.serviceType==='consultancy'?'consultancy':e?.type||'income')}${input('amount',e?'Valor desta parcela (R$)':'Valor total (R$)',e?(e.amountCents/100).toFixed(2):'','number','min="0.01" step="0.01" required')}${!e?input('installments','Parcelas mensais',1,'number','min="1" max="120" required'):''}${input('dueDate','Vencimento / primeira parcela',e?.dueDate||data.today,'date','required')}${input('competenceDate','Competência / primeira parcela',e?.competenceDate||data.today,'date','required')}${select('accountId','Conta de origem',cats('account',e?.accountId,true),e?.accountId,'Sem conta')}${select('toAccountId','Conta destino (transferência)',cats('account',e?.toAccountId,true),e?.toAccountId,'Selecione para transferência')}${select('categoryId','Categoria',cats('category',e?.categoryId),e?.categoryId,'Sem categoria')}${select('personId','Cliente / fornecedor',cats('person',e?.personId),e?.personId,'Sem vínculo')}${select('clientId','Cliente da agência',clientOptions(),e?.clientId,'Conforme a viagem')}${select('tripId','Viagem',tripOptions(),e?.tripId,'Sem vínculo')}${input('document','Documento / referência',e?.document)}<label class="fin-wide">Observações<textarea name="notes" maxlength="5000">${esc(e?.notes)}</textarea></label>${!e?'<p class="fin-muted fin-wide">O valor total será dividido entre as parcelas. Vencimento e competência avançam um mês por parcela.</p>':''}`));if(e?.linkVersion){for(const key of ['clientId','tripId'])root.querySelector('[data-fin-form=entry]').elements[key].disabled=true;}}
    async function detail(id){const [e,h]=await Promise.all([request('/entries/'+encodeURIComponent(id)),request('/entries/'+encodeURIComponent(id)+'/history')]);if(!alive())return;selected=e;modal(e.title,`<div class="fin-detail"><p>${types[e.serviceType==='consultancy'?'consultancy':e.serviceType==='commission'?'commission':e.type]} · ${statuses[status(e,data.today)]}</p><h3>${money(e.type==='opening'?e.openingSignedCents:e.amountCents)}</h3><p>Em aberto: ${money(e.canceled?0:e.amountCents-paid(e))} · Vencimento: ${date(e.dueDate)} · Competência: ${date(e.competenceDate)}</p><p>Conta: ${esc(name(e.accountId))}${e.toAccountId?' → '+esc(name(e.toAccountId)):''}<br>Categoria: ${esc(name(e.categoryId))}<br>Cliente / fornecedor: ${esc(name(e.personId))}</p><p>${esc(e.document)}</p><p class="fin-notes">${esc(e.notes)}</p>${e.source==='granatum'?granatumDetails(e):''}<div class="fin-actions">${e.source!=='granatum'?`${!e.canceled?button('edit','Editar',id):''}${!e.canceled&&paid(e)<e.amountCents?button('pay','Registrar baixa',id,'class="fin-primary"'):''}${data.manager?button(e.canceled?'restore':'cancel',e.canceled?'Reabrir':'Cancelar lançamento',id):''}`:''}</div>${e.legacyPaid?`<p class="fin-warning">Baixa anterior sem data registrada. O valor foi preservado, mas não compõe o fluxo realizado nem o saldo das contas. Para regularizar, estorne esta baixa e registre a data correta.</p>${data.manager?button('reverse','Estornar baixa anterior','legacy'):''}`:''}<section class="fin-link"><h3>Vínculo com a operação</h3><p>${esc(data.clients?.find(c=>c.id===e.clientId)?.name||'Cliente não vinculado')} · ${esc(trips.find(t=>t.id===e.tripId)?.title||'Viagem não vinculada')}</p>${button('link','Vincular cliente / viagem')}</section><h3>Baixas registradas</h3>${e.payments.map(p=>`<div class="fin-payment"><span>${date(p.date)} · ${money(p.amountCents)}<small>${esc(p.note)}</small></span>${data.manager&&e.source!=='granatum'?button('reverse','Estornar',p.id):''}</div>`).join('')||'<p class="fin-muted">Nenhuma baixa com data registrada.</p>'}<h3>Histórico de alterações</h3><ol class="fin-history">${h.events.map(v=>`<li>${esc(new Date(v.created_at).toLocaleString('pt-BR'))} · ${esc(({granatum_sync:'Sincronizado do Granatum',granatum_deleted:'Excluído no Granatum',created:'Criado',create:'Criado',edited:'Editado',payments:'Baixa registrada',reverse:'Baixa estornada',cancel:'Cancelado',restore:'Reaberto',bootstrap:'Importado do histórico'})[v.action]||v.action)}${v.reason?' — '+esc(v.reason):''}</li>`).join('')}</ol></div>`);}
    const clientOptions=()=>Object.fromEntries((data.clients||[]).map(c=>[c.id,c.name]));
    const tripOptions=()=>Object.fromEntries(trips.map(t=>[t.id,t.title]));
    const known=v=>v===null?'<span class="fin-pending">A informar</span>':money(v);
    function insightFilters(){return `<form data-fin-form="filter" class="fin-filters fin-insight-filters"><div class="fin-filter-fields">${select('allTime','Período',{1:'Todo o histórico'},filters.allTime||'','Selecionar datas')}${input('from','De',filters.from,'date','required')}${input('to','Até',filters.to,'date','required')}${select('clientId','Cliente',clientOptions(),filters.clientId,'Todos')}${select('tripId','Viagem',tripOptions(),filters.tripId,'Todas')}${input('q','Buscar viagem ou cliente',filters.q)}<div class="fin-filter-actions"><button class="fin-primary">Aplicar filtros</button></div></div><p class="fin-muted">Período pela data de confirmação ou venda. Sem essa data, usamos o início da viagem, identificado em cada operação.</p></form>`;}
    function operationsView(){if(!insights)return '';const s=insights.summary;return `<div class="fin-section-heading"><div><h2>O resultado de cada operação</h2><p>Viagens confirmadas e emitidas entram automaticamente aqui. Recebimentos e pagamentos continuam na aba Lançamentos.</p></div><span class="fin-count">${s.operations} operações</span></div><div class="fin-summary">${[['Volume vendido',s.volumeCents],['Comissões conhecidas',s.commissionCents],['Receita da agência*',s.revenueCents],['Resultado conhecido*',s.resultCents]].map(([label,value])=>`<article><span>${label}</span><strong>${money(value)}</strong></article>`).join('')}</div><p class="fin-muted">*Receita: comissão + consultoria. Resultado: receita menos custos diretos informados, antes de despesas gerais e tributos. ${s.incomplete?s.incomplete+' operação(ões) com valores pendentes; os totais são parciais.':'Valores informados em todas as operações deste período.'} ${insights.undated?insights.undated+' operação(ões) sem data: selecione Todo o histórico para conferir.':''}</p><div class="fin-table"><table><thead><tr><th>Viagem / cliente</th><th>Volume vendido</th><th>Comissão</th><th>Consultoria</th><th>Resultado*</th><th></th></tr></thead><tbody>${insights.operations.map(o=>`<tr><td><strong>${esc(o.title)}</strong><small>${esc(o.clientName)} · ${esc(o.status)}</small><small>${date(o.date)} · ${esc(o.dateBasis)}</small></td><td>${known(o.volumeCents)}</td><td>${known(o.commissionCents)}</td><td>${money(o.consultancyCents)}</td><td>${known(o.resultCents)}</td><td>${button('operation','Conferir valores',o.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="fin-empty">Nenhuma operação no período. Selecione Todo o histórico para incluir viagens antigas e sem data.</td></tr>'}</tbody></table></div>`;}
    function clientsView(){if(!insights)return '';return `<div class="fin-section-heading"><div><h2>Compras, recorrência e indicações</h2><p>Ordenado pelo volume vendido no período. Compras consideram as viagens confirmadas ou emitidas; o relacionamento é uma avaliação registrada pela agência.</p></div></div><div class="fin-table"><table><thead><tr><th>Cliente</th><th>Volume no período</th><th>Compras</th><th>Indicações</th><th>Relacionamento</th><th></th></tr></thead><tbody>${insights.clients.map((c,i)=>`<tr><td><strong>${i+1}. ${esc(c.name)}</strong><small>${esc(c.origin||'Origem não informada')}${c.referredByName?' · Indicação de '+esc(c.referredByName):''}</small></td><td>${money(c.volumeCents)}${c.missingValues?'<small>Há valores pendentes</small>':''}</td><td>${c.purchases} no período<small>${c.lifetimePurchases} no histórico · ${c.lifetimePurchases>1?'Recorrente':c.lifetimePurchases?'Primeira compra':'Sem compra'}</small></td><td>${c.referrals}</td><td>${esc(c.relationship||'Não avaliado')}</td><td>${button('client-history','Ver histórico',c.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="fin-empty">Nenhum cliente encontrado.</td></tr>'}</tbody></table></div>`;}
    function clientHistory(id){const c=insights.clients.find(c=>c.id===id);modal(c.name,`<div class="fin-detail"><p>${c.lifetimePurchases} compras no histórico · ${c.referrals} indicações</p><p>Origem: ${esc(c.origin||'Não informada')}<br>Indicado por: ${esc(c.referredByName||'Não informado')}<br>Relacionamento: ${esc(c.relationship||'Não avaliado')}</p><a class="fin-profile-link" href="clientes.html#cliente/${encodeURIComponent(c.id)}">Abrir perfil e editar relacionamento →</a><h3>Histórico de viagens</h3>${c.trips.map(t=>`<a class="fin-history-trip" href="viagens.html#viagem/${encodeURIComponent(t.id)}"><strong>${esc(t.title)}</strong><span>${esc(t.status)} · ${date(t.start)}</span><span>${t.value?money(t.value*100):'Valor a informar'} →</span></a>`).join('')||'<p>Nenhuma viagem vinculada.</p>'}</div>`);}
    function operationForm(id){const o=insights.operations.find(o=>o.id===id);selected=o;const m=o.metadata,decimal=v=>v==null?'':(v/100).toFixed(2);modal('Resultado · '+o.title,form('operation',`<p class="fin-wide fin-muted">${esc(o.clientName)} · Volume vendido: ${o.volumeCents===null?'a informar':money(o.volumeCents)}. Preencha a comissão em reais ou percentual. Valor em branco permanece pendente; zero é um valor informado.</p>${select('commissionMode','Como informar a comissão',{amount:'Valor em reais',percent:'Percentual da venda'},m.commissionMode||'amount')}${input('saleDate','Data da venda / confirmação',m.saleDate||'','date')}<label data-commission="amount">Comissão (R$)<input name="commission" type="number" min="0" step="0.01" value="${decimal(m.commissionCents)}"></label><label data-commission="percent">Comissão (%)<input name="commissionRate" type="number" min="0" max="100" step="0.01" value="${m.commissionMode==='percent'?esc(m.commissionRate):''}"></label>${input('consultancy','Consultoria (R$)',decimal(o.consultancyLinked?o.consultancyCents:m.consultancyCents),'number','min="0" step="0.01"'+(o.consultancyLinked?' disabled':''))}${input('costs','Custos diretos da agência (R$)',decimal(o.costsLinked?o.costsCents:m.costsCents),'number','min="0" step="0.01"'+(o.costsLinked?' disabled':''))}<p class="fin-wide fin-muted">Custos diretos são os gastos suportados pela agência nesta operação. ${o.costsLinked||o.consultancyLinked?'Consultorias e custos já vinculados são calculados pelos lançamentos; revise-os na aba Lançamentos.':''} ${o.commissionLinked?'Há comissão vinculada. Um valor manual substitui esse total na projeção, sem somar duas vezes.':''} Estes valores gerenciais não registram pagamento ou recebimento. Sem data de venda, permanece a base indicada na lista.</p><label class="fin-wide">Observações<textarea name="notes" maxlength="3000">${esc(m.notes)}</textarea></label><div class="fin-wide fin-actions">${button('operation-entries','Ver lançamentos vinculados',o.id)}</div>`));commissionFields();}
    function commissionFields(){const f=root.querySelector('[data-fin-form="operation"]');if(!f)return;for(const label of f.querySelectorAll('[data-commission]')){const enabled=label.dataset.commission===f.elements.commissionMode.value;label.hidden=!enabled;label.querySelector('input').disabled=!enabled;label.querySelector('input').required=enabled&&label.dataset.commission==='percent';}}
    function linkForm(){const e=selected;modal('Vincular lançamento',form('link',`<p class="fin-muted fin-wide">${esc(e.title)}. O vínculo organiza os relatórios do TravelPro e preserva o lançamento original, inclusive no Granatum.</p>${select('clientId','Cliente da agência',clientOptions(),e.clientId,'Conforme a viagem')}${select('tripId','Viagem',tripOptions(),e.tripId,'Sem vínculo')}${['income','commission'].includes(e.type)?select('serviceType','Natureza para o resultado',{commission:'Comissão',consultancy:'Consultoria'},e.serviceType,'Tipo original'):''}`));}
    function reportsForm(){modal('Baixar relatório',`<form data-fin-form="report" class="fin-form">${select('report','Conteúdo',{entries:'Lançamentos de caixa',operations:'Resultado por viagem',clients:'Clientes e compras'},['operations','clients'].includes(tab)?tab:'entries')}${select('allTime','Período das operações',{1:'Todo o histórico'},filters.allTime||'','Selecionar datas')}${input('from','De',filters.from,'date','required')}${input('to','Até',filters.to,'date','required')}${select('type','Tipo de lançamento',types,filters.type,'Todos')}${select('clientId','Cliente',clientOptions(),filters.clientId,'Todos')}${select('tripId','Viagem',tripOptions(),filters.tripId,'Todas')}<p class="fin-wide fin-muted">Arquivo CSV para abrir no Excel ou em planilhas. O relatório de caixa utiliza vencimento e o intervalo de datas; tipo é aplicado apenas aos lançamentos. Relatórios de operações identificam valores pendentes e a base de cada data.</p><div class="fin-form-footer"><button class="fin-primary">Baixar CSV</button>${button('close','Cancelar')}</div></form>`);reportFields();}
    function reportFields(){const f=root.querySelector('[data-fin-form="report"]');if(!f)return;const cash=f.elements.report.value==='entries';f.elements.type.disabled=!cash;f.elements.allTime.disabled=cash;for(const key of ['from','to'])f.elements[key].disabled=!cash&&f.elements.allTime.value==='1';}
    async function downloadReport(values){const {report,...params}=values;const result=await request((report==='entries'?'/export?':'/insights?export='+report+'&')+new URLSearchParams(params));const url=URL.createObjectURL(new Blob([result.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`travelpro-${report}-${values.allTime==='1'&&report!=='entries'?'historico':values.from+'-'+values.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    root.addEventListener('change',event=>{if(event.target.name==='commissionMode')commissionFields();if(event.target.closest('[data-fin-form="report"]'))reportFields();if(event.target.name==='tripId'&&event.target.closest('[data-fin-form="entry"],[data-fin-form="link"]')){const t=trips.find(t=>t.id===event.target.value),f=event.target.form;if(t)f.elements.clientId.value=t.client;}if(event.target.name==='allTime'&&event.target.closest('.fin-insight-filters')){for(const key of ['from','to'])event.target.form.elements[key].disabled=event.target.value==='1';}});
    function catalogForm(kind,c){selected=c||null;modal(c?'Editar cadastro':'Novo cadastro',form('catalog',`<input type="hidden" name="kind" value="${kind}">${input('name','Nome',c?.name,'text','required maxlength="150"')}${kind==='account'?input('openingAmount','Saldo inicial (R$)',((c?.openingCents||0)/100).toFixed(2),'number','step="0.01" required')+input('openingDate','Data do saldo inicial',c?.openingDate||data.today,'date',`required max="${data.today}"`)+'<p class="fin-muted fin-wide">Informe o saldo antes das movimentações dessa data. Alterar o saldo inicial recalcula o saldo atual.</p>':kind==='category'?select('type','Aplicação',{income:'Receitas',expense:'Despesas',both:'Ambos'},c?.type||'both'):select('role','Tipo',{client:'Cliente',supplier:'Fornecedor',both:'Ambos'},c?.role||'supplier')+input('email','E-mail',c?.email,'email')+input('document','CPF / CNPJ',c?.document)+input('phone','Telefone',c?.phone)}`));}
    root.addEventListener('click',async event=>{const b=event.target.closest('[data-fin-action]');if(!b||!root.contains(b)||busy)return;const action=b.dataset.finAction,id=b.dataset.id;try{
      if(action==='granatum-range'){filters={...filters,from:granatum.stats.from,to:granatum.stats.to,source:'granatum',page:1};tab='entries';return await load();}
      if(action==='granatum-sync'||action==='granatum-restart'){busy=true;b.disabled=true;b.textContent='Sincronizando...';const result=await request('/granatum/sync','POST',{restart:action==='granatum-restart'});await load();notice(result.running?'Sincronização em andamento. O servidor continuará automaticamente.':'Granatum atualizado.');return;}
      if(action==='close'){root.querySelector('dialog').close();return;}
      if(action==='tab'){tab=id;if(['operations','clients'].includes(tab))return await load();draw();return;}
      if(action==='refresh')return await load();
      if(action==='previous'||action==='next'){filters.page=Number(filters.page)+(action==='next'?1:-1);return await load();}
      if(action==='reports')return reportsForm();
      if(action==='operation')return operationForm(id);
      if(action==='client-history')return clientHistory(id);
      if(action==='link')return linkForm();
      if(action==='operation-entries'){filters={...filters,from:'1900-01-01',to:'9999-12-31',tripId:id,page:1};tab='entries';return await load();}
      if(action==='new')return entryForm();
      if(action==='detail')return await detail(id);
      if(action==='edit')return entryForm(selected);
      if(action==='pay')return modal('Registrar baixa',form('payment',input('amount','Valor da baixa (R$)',((selected.amountCents-paid(selected))/100).toFixed(2),'number','required min="0.01" step="0.01"')+input('date','Data do recebimento / pagamento',data.today,'date',`required max="${data.today}"`)+input('note','Observação')));
      if(['reverse','cancel','restore'].includes(action))return modal(action==='reverse'?'Estornar baixa':action==='cancel'?'Cancelar lançamento':'Reabrir lançamento',form('reason',`<input type="hidden" name="action" value="${action}"><input type="hidden" name="paymentId" value="${esc(id)}">${input('reason','Motivo','','text','required minlength="3" maxlength="500"')}`));
      if(action==='catalog-new')return catalogForm(id);
      if(action==='catalog-edit'){const c=data.catalogs.find(c=>c.id===id);return catalogForm(c.kind,c);}
      if(action==='archive'){const c=data.catalogs.find(c=>c.id===id);busy=true;await request('/catalogs/'+id,'PUT',{version:c.version,archive:!c.archived});return await load();}
      if(action==='export'){busy=true;b.disabled=true;const result=await request('/export?'+query());const url=URL.createObjectURL(new Blob([result.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`travelpro-financeiro-${filters.from}-${filters.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    }catch(e){showError(e);}finally{busy=false;b.disabled=false;}});
    function showError(e){const d=root.querySelector('dialog');if(d?.open){const el=d.querySelector('[data-fin-error]');el.textContent=e.message;el.hidden=false;}else notice(e.message);}
    root.addEventListener('submit',async event=>{const f=event.target.closest('[data-fin-form]');if(!f)return;event.preventDefault();if(busy)return;const values=Object.fromEntries(new FormData(f)),kind=f.dataset.finForm;if(kind==='filter'){filters={...values,page:1};await load();return;}busy=true;const submit=f.querySelector('button');submit.disabled=true;try{
      if(kind==='report'){await downloadReport(values);root.querySelector('dialog').close();return;}
      if(kind==='operation')await request('/operations/'+encodeURIComponent(selected.id),'PUT',{...values,version:selected.metadata.version||0});
      if(kind==='link')await request('/entries/'+encodeURIComponent(selected.id)+'/link','PUT',{...values,version:selected.linkVersion||0});
      if(kind==='entry')await request('/entries'+(selected?'/'+selected.id:''),selected?'PUT':'POST',{...values,...(selected?{version:selected.version}:{})});
      if(kind==='catalog')await request('/catalogs'+(selected?'/'+selected.id:''),selected?'PUT':'POST',{...values,...(selected?{version:selected.version}:{})});
      if(kind==='payment')await request('/entries/'+selected.id+'/payments','POST',{...values,version:selected.version});
      if(kind==='reason')await request('/entries/'+selected.id+'/'+values.action,'POST',{...values,version:selected.version});
      root.querySelector('dialog').close();const refreshed=await load();notice(refreshed?'Alteração salva.':'Alteração salva. Não foi possível atualizar a lista. Use Atualizar.');
    }catch(e){showError(e);}finally{busy=false;submit.disabled=false;}});
    load();
  }};
})();
